/* КОНТРОЛЬ ВВОДА — пример фонового плагина: работает без панели, с
   установки и до удаления. Показывает три вещи из раздела 4а описания API:
   события книги, пункты меню на любой клетке и свою группу на ленте.
   Снимок книги ему не нужен («читает»: «ничего») — всё, что надо, приходит
   в поводе события или читается по запросу (итог считает ядро). */

/* Правка в книге: отрицательное число — скажем об этом сразу. В поводе есть
   первые сто изменённых клеток; своих правок плагин не получает, так что
   зацикливания тут нет. */
async function ПриИзменении(){
  const п = книга.повод;
  if(п.строение) return;                              // вставили или удалили строки — не наш случай
  const плохие = п.клетки.filter(к => typeof к.значение === 'number' && к.значение < 0);
  if(плохие.length)
    await диалог.сообщение('Отрицательное число: ' + плохие.map(к => к.лист + '!' + к.адрес).join(', '));
}

/* Меню клетки: пункты по обстоятельствам — их возвращает функция. */
function Меню(){
  const п = книга.повод;
  if(typeof п.значение === 'number' && п.значение < 0) return [{имя: 'Сделать положительным', функция: 'Положительное'}];
  return [];
}
function Положительное(){ const п = книга.повод; ячейка(п.адрес).значение = -п.значение; }

/* Пункты «везде» из описания: на числах и на тексте. */
function Удвоить(){ const п = книга.повод; ячейка(п.адрес).значение = п.значение * 2; }
function Верхний(){ const п = книга.повод; ячейка(п.адрес).значение = String(п.значение).toUpperCase(); }

/* Кнопка ленты: итог по выделению считает ядро прямо по хранилищу. */
async function Итог(){
  const в = книга.выделение, л = лист(в.лист);
  const [сумма, чисел] = await Promise.all([л.итог('СУММ', в.область), л.итог('СЧЁТ', в.область)]);
  await диалог.сообщение(в.область + ': чисел ' + чисел + ', сумма ' + сумма);
}
